  ('a84435a1-c622-4e4c-98ad-018d6c80fed0', 'Yanaka Ginza & cats', 'place', 'Yanaka', 35.7277, 139.7669, null, 29, false, '[{"key": "info", "value": "Time-capsule old Tokyo — retro shopping street, sunset steps, temple lanes, resident cats."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/9a/Nippori_Station.jpg/330px-Nippori_Station.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('4e026193-3a94-45c0-8bad-6a57b0c05d07', 'Kagurazaka evening stroll', 'place', 'Kagurazaka', 35.702, 139.74, null, 30, false, '[{"key": "info", "value": "Cobbled former geisha district — stone alleys, hidden French bistros. Chic, romantic, low-tourist."}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('5aeb8152-59a8-42b6-9669-69c93530b462', 'Jimbocho book town', 'shop', 'Jimbocho, Chiyoda', 35.6959, 139.7578, null, 31, false, '[{"key": "info", "value": "~150 second-hand bookshops + old-school coffee houses — cheap vintage prints."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b0/Yaguchi_Book_Store_and_Koga_Book_Store.jpg/330px-Yaguchi_Book_Store_and_Koga_Book_Store.jpg"}]', '["Ukiyo-e prints", "Vintage books"]'),
  ('25039666-a03b-4b0a-aa1d-39caf2efa426', 'Shimokitazawa thrift & live houses', 'place', 'Shimokitazawa', 35.6613, 139.6682, null, 32, false, '[{"key": "info", "value": "Bohemian thrift, indie records, tiny live venues (entry ~¥2,500–3,500 +1 drink). Koenji is the punkier, cheaper cousin."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/12/Puces_de_Montsoreau.jpg/330px-Puces_de_Montsoreau.jpg"}, {"key": "duration", "value": "2h"}]', '[]'),
  ('5d127c74-7e13-465c-b9b6-3f1736dd046c', 'Nakameguro canal cafés', 'place', 'Nakameguro', 35.644, 139.6982, null, 33, false, '[]', '[]'),
  ('707d1931-f528-4ed2-820a-7bf00b68b471', 'Depachika food halls', 'food', 'Isetan Shinjuku / Ginza', 35.6916, 139.7045, null, 34, false, '[{"key": "info", "value": "Jewel-like basement food halls — bento, wagashi, free samples. The most beautiful edible window-shopping on earth."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/49/Mitsukoshi_Nihonbashi_main_store_9.jpg/330px-Mitsukoshi_Nihonbashi_main_store_9.jpg"}]', '[]'),
  ('ccf117ad-cff6-4ea2-a445-9cd50fa20ae4', 'Pokémon Cafe', 'food', 'Nihonbashi', 35.684, 139.7745, null, 35, false, '[{"key": "info", "value": "Reservation required; sets ¥1,500–3,000. Kirby Cafe at Skytree is the alternative."}]', '[]'),
  ('4a84a18b-93d9-45e3-8510-a9aedbdb9609', 'Meiji Gaien Ginkgo Avenue', 'place', 'Aoyama', 35.6746, 139.7176, null, 36, false, '[{"key": "info", "value": "Tokyo''s most famous golden-ginkgo tunnel — colour usually mid-to-late Nov (early for this trip, still a lovely walk)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/%E8%81%96%E5%BE%B3%E8%A8%98%E5%BF%B5%E7%B5%B5%E7%94%BB%E9%A4%A8.jpg/330px-%E8%81%96%E5%BE%B3%E8%A8%98%E5%BF%B5%E7%B5%B5%E7%94%BB%E9%A4%A8.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('42a80da2-f117-4959-9ffb-202a80322057', 'Todoroki Valley walk', 'place', 'Setagaya', 35.6089, 139.6482, null, 37, false, '[{"key": "info", "value": "A leafy ravine stream-walk that feels like countryside inside Tokyo. Free."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Komazawa_Gymnasium_%26_Control_Tower_2009.jpg/330px-Komazawa_Gymnasium_%26_Control_Tower_2009.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('a24267c2-df48-4028-bd41-d4e2d13d7c11', 'Nikko day trip', 'experience', 'Toshogu, Nikko (~2 h)', 36.7581, 139.5986, null, 38, false, '[{"key": "info", "value": "THE October foliage pick — Toshogu''s carved UNESCO shrines, Kegon Falls, Lake Chuzenji, and the 48 Irohazaka switchbacks peaking late Oct.\nTobu Spacia from Asakusa ~2 h; Nikko passes from ~¥3,000. Start early."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Lake_chuzenji_and_kegon_waterfall.jpg/330px-Lake_chuzenji_and_kegon_waterfall.jpg"}, {"key": "duration", "value": "9h"}]', '[]'),
  ('5381d874-0bf2-4b6e-ad83-d1fdb184f924', 'Kamakura + Enoshima', 'experience', 'Kamakura (~1 h)', 35.3167, 139.5504, null, 39, false, '[{"key": "info", "value": "Great Buddha (¥300), Hase-dera, the Enoden coastal tram, surf beach, Enoshima''s shrine lanes + Iwaya caves. The do-everything day."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/cf/230128_Kamakura_Daibutsu_Japan04s3.jpg/330px-230128_Kamakura_Daibutsu_Japan04s3.jpg"}, {"key": "duration", "value": "9h"}]', '[]'),
  ('6f1f21d9-2511-40cb-b834-aef2dc7ad0b2', 'Yokohama half-day', 'experience', 'Minato Mirai (~30 min)', 35.456, 139.638, null, 40, false, '[{"key": "info", "value": "Japan''s biggest Chinatown (graze!), Cup Noodles Museum (make your own), harbour Ferris wheel, Red Brick Warehouse. Lowest-effort trip on the list."}, {"key": "duration", "value": "5h"}]', '[]'),
  ('414c98c1-f766-46da-bd2d-83512781ceb1', 'Fuji-Q + Kawaguchiko', 'experience', 'Fuji Five Lakes (~2 h)', 35.487, 138.7809, null, 41, false, '[{"key": "info", "value": "Fuji icons + world-record coasters (Takabisha''s 121° drop). 1-day pass ¥6,000–7,800 — book timed tickets online. October = snow-capped clarity."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Ohio_-_Cedar_Point_1.jpg/330px-Ohio_-_Cedar_Point_1.jpg"}, {"key": "duration", "value": "10h"}]', '[]'),
  ('b77cc9f2-e93c-4690-98f3-f9e4aad7295a', 'Chureito Pagoda', 'place', 'Fujiyoshida (~2 h)', 35.5017, 138.801, null, 42, false, '[{"key": "info", "value": "The single most iconic \"Japan\" photo — five-storey pagoda + Fuji, ~400 steps up. Worth the trip on a clear day; unreal in autumn."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Chuurei-tou_Fujiyoshida_17025277650_c59733d6ba_o.jpg/330px-Chuurei-tou_Fujiyoshida_17025277650_c59733d6ba_o.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('9d77e010-8592-4f43-b490-033036336dd8', 'Nokogiriyama hell-peek', 'experience', 'Chiba (~2 h)', 35.1595, 139.832, null, 43, false, '[{"key": "info", "value": "Stand on the Jigoku Nozoki cliff ledge, then Japan''s biggest stone Buddha (31 m). Ropeway ¥1,200 round trip; pair with the Tokyo Bay ferry."}, {"key": "duration", "value": "6h"}]', '[]'),
  ('d4060228-fdde-4106-8bc2-18de7871d190', 'Sawara canal town', 'place', 'Chiba (~1 h 50)', 35.8886, 140.4996, null, 44, false, '[{"key": "info", "value": "The quieter \"Little Edo\" — willow canals, merchant houses, wooden boat cruise (reserve on busy days)."}, {"key": "duration", "value": "5h"}]', '[]'),
  ('57eb3b9d-5b72-47be-952d-24bd511aac11', 'Kusatsu Onsen (overnight)', 'experience', 'Gunma (~4 h)', 36.6206, 138.5964, null, 45, false, '[{"key": "info", "value": "Japan''s most famous onsen town — the steaming Yubatake, yumomi paddle show, riverside rotenburo. Over the 2-h line; better as an overnight (book early)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Tanigawadake_Ropeway.jpg/330px-Tanigawadake_Ropeway.jpg"}, {"key": "duration", "value": "8h"}]', '[]'),
  ('05384e76-cc6a-4cb1-9256-026bcd004158', 'Kinkaku-ji (Golden Pavilion)', 'place', 'NW Kyoto', 35.0394, 135.7292, null, 46, false, '[{"key": "info", "value": "Gold-leaf Zen pavilion mirrored in its pond. ¥500. Small and jams fast — be at the gate at 9:00 opening."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Golden_Pavilion_Kinkaku-ji_water_mirror_2024.jpg/330px-Golden_Pavilion_Kinkaku-ji_water_mirror_2024.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('9c5c80f7-65c4-44b4-a3b6-bf4cb3496f3c', 'Ryoan-ji rock garden', 'place', 'NW Kyoto', 35.0345, 135.7182, null, 49, false, '[{"key": "info", "value": "Japan''s most famous Zen rock garden — 15 stones. ¥600; early morning you can actually sit in silence. Near Kinkaku-ji."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg/330px-Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('68c44178-9b28-4a0b-a02f-efe196e42171', 'Nanzen-ji & the aqueduct', 'place', 'NE Higashiyama', 35.011, 135.7943, null, 50, false, '[{"key": "info", "value": "Grand Zen complex with a photogenic brick aqueduct — free grounds, low crowds, any time."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/251213_Nanzen-ji_Kyoto_Japan01s3.jpg/330px-251213_Nanzen-ji_Kyoto_Japan01s3.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('704a056d-d4b7-4dae-8a90-92aa1a402e68', 'Sanjusangen-do', 'place', 'E of Kyoto Station', 34.9878, 135.7716, null, 52, false, '[{"key": "info", "value": "1,001 gold Kannon statues in one long hall — jaw-dropping, indoors (great for midday). ¥600; no photos."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Sanjusangendo_2022.jpg/330px-Sanjusangendo_2022.jpg"}, {"key": "duration", "value": "1h"}]', '[]'),
  ('ee406b84-fb5f-4035-aa52-56b85cf14a5f', 'Tea ceremony in kimono', 'experience', 'Maikoya, Kyoto', 35.0049, 135.7646, null, 53, false, '[{"key": "info", "value": "Whisk matcha on tatami with a tea master, dressed in kimono — from ~¥10,000 (90 min incl. kimono + wagashi). Weekends sell out, book days ahead."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/2023_Fuyuko_Kobori_Traditional_Tea_Ceremony_Gokokuji_Temple.jpg/330px-2023_Fuyuko_Kobori_Traditional_Tea_Ceremony_Gokokuji_Temple.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('a8400704-9e64-453c-bb01-e40cae065d13', 'Wagashi-making class', 'experience', 'Downtown Kyoto', 35.008, 135.76, null, 54, false, '[{"key": "info", "value": "Shape your own seasonal Kyoto sweets, then eat them with matcha. ~¥2,500–3,500 — book ahead."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/01/11-11-06-FarEastCafe-LittleTokyo.jpg/330px-11-11-06-FarEastCafe-LittleTokyo.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('2db598ab-c667-4570-a75a-b6a1910384bb', 'Zazen meditation with a monk', 'experience', 'Zen temples, Kyoto', 35.011, 135.7943, null, 55, false, '[{"key": "info", "value": "Sit zazen, often with garden + shojin (Buddhist) lunch options. ~¥1,000–3,000; some temples English-guided — reserve."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5c/Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg/330px-Kare-sansui_zen_garden%2C_Ry%C5%8Dan-ji%2C_Kyoto_20190416_1.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('20d6e62d-e0df-4404-b388-fefcaa784071', 'Daimonji sunset hike', 'experience', 'From Ginkaku-ji', 35.025, 135.801, null, 57, false, '[{"key": "info", "value": "~1 h climb to the giant 大 bonfire site — the best free view over all Kyoto. Do it at sunset."}, {"key": "duration", "value": "2h 30m"}]', '[]'),
  ('4362723b-e404-43a7-9b3c-dbef01513cba', 'Kaiseki lunch bargain', 'food', 'Citywide, Kyoto', 35.006, 135.77, null, 59, false, '[{"key": "info", "value": "Kyoto''s refined multi-course art at a fraction of dinner price — ¥3,000–6,000. Book lunch to eat high-end cheaply."}]', '[]'),
  ('417ddbd2-588c-47a8-a40e-e8fdfe7cb847', 'Samurai & Ninja experience', 'experience', 'Samurai & Ninja Museum, Nakagyo', 35.005, 135.767, null, 60, true, '[{"key": "info", "value": "Armour, shuriken throwing, sword lesson — ~¥2,500–4,000, ~1.5 h.\nKeep the morning light: tonight is the trip''s biggest night."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/89/Honnoji5965.JPG/330px-Honnoji5965.JPG"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('9bec5472-cf31-4d59-bee8-ed72dd34322c', 'Yudofu by Nanzen-ji', 'food', 'Nanzen-ji area', 35.0106, 135.792, null, 60, false, '[{"key": "info", "value": "Zen temple-style simmered tofu — Kyoto''s signature vegetarian dish, warming in autumn. ~¥3,000."}]', '["Yudofu (tofu hot pot)"]'),
  ('34352944-2f33-4023-b9ec-d4d14cf89039', 'Kyoto Manga Museum', 'place', 'Central Kyoto', 35.0119, 135.7593, null, 61, false, '[{"key": "info", "value": "300,000 manga you can pull off the walls and read on the lawn. ~¥1,200 — the ideal crowded-midday retreat."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/%E4%BA%AC%E9%83%BD%E5%9B%BD%E9%9A%9B%E3%83%9E%E3%83%B3%E3%82%AC%E3%83%9F%E3%83%A5%E3%83%BC%E3%82%B8%E3%82%A2%E3%83%A0.jpg/330px-%E4%BA%AC%E9%83%BD%E5%9B%BD%E9%9A%9B%E3%83%9E%E3%83%B3%E3%82%AC%E3%83%9F%E3%83%A5%E3%83%BC%E3%82%B8%E3%82%A2%E3%83%A0.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('726b7f2b-2288-4952-8c1d-6f7db0b6a665', 'Jidai Matsuri procession', 'experience', 'Imperial Palace → Heian Shrine', 35.0254, 135.7621, null, 61, false, '[{"key": "time", "value": "12:00"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/16/JidaiMatsuri_Gohouren.jpg/330px-JidaiMatsuri_Gohouren.jpg"}, {"key": "duration", "value": "3h"}, {"key": "info", "value": "\"Festival of the Ages\" — 2,000 people in 1,000+ years of accurate historical costume.\nLeaves the Imperial Palace ~12:00, reaches Heian Shrine ~14:30. Grab a kerb spot on Oike-dori early; paid grandstand seats sell out.\nSkipping the daytime procession — attending the Kurama Fire Festival at night instead."}]', '[]'),
  ('c466af50-3c25-402a-9298-6168f82c7416', 'Uji matcha half-day', 'experience', 'Uji (~30 min)', 34.8894, 135.8075, null, 62, false, '[{"key": "info", "value": "The matcha capital: Byodo-in Phoenix Hall (the ¥10-coin building, ¥700 — bring a coin), grind-your-own matcha (~¥1,000–1,500), Nakamura Tokichi parfaits.\nOctober = up to 1.5 h waits for the hall interior; go early."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3f/Casual_tea_set%40Japan.jpg/330px-Casual_tea_set%40Japan.jpg"}, {"key": "duration", "value": "5h"}]', '[]'),
  ('323ef968-1309-4a44-8651-3ae05d0ffb10', 'Umeda Sky sunset', 'place', 'Umeda Sky Building', 34.7052, 135.4899, null, 62, false, '[{"key": "info", "value": "The open-air rooftop ring at 173 m — Osaka''s best sunset. ¥2,000."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f9/2018_Umeda_Sky_Building.jpg/330px-2018_Umeda_Sky_Building.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('05677f1a-3f34-4d65-aa4f-d5f796a2bfe8', 'Fushimi sake tasting', 'experience', 'Gekkeikan Okura Museum, Fushimi', 34.9298, 135.762, null, 63, false, '[{"key": "info", "value": "¥600 incl. tasting, 9:30–16:30 — one of the world''s oldest sake makers, in the willow-lined canal brewery district (~40 breweries)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Torii_path_with_lantern_at_Fushimi_Inari_Taisha_Shrine%2C_Kyoto%2C_Japan.jpg/330px-Torii_path_with_lantern_at_Fushimi_Inari_Taisha_Shrine%2C_Kyoto%2C_Japan.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('b9137d2c-e7e9-453c-86e8-2961885c408e', 'Kodai-ji night illumination', 'experience', 'Higashiyama', 35.0006, 135.7815, null, 63, false, '[{"key": "time", "value": "19:00"}, {"key": "info", "value": "Night-lit gardens + projection mapping, Oct 24–Dec 14, ¥600. Weeknights at opening beat the crowds."}, {"key": "duration", "value": "1h"}]', '[]'),
  ('20239cea-0052-45b6-84dc-e38db2549e9b', 'Private maiko dinner (splurge)', 'experience', 'Gion', 35.0037, 135.7754, null, 64, false, '[{"key": "info", "value": "Dine with a real maiko — games, dance, conversation. ~¥40,000–100,000+ pp; small capacity, book weeks ahead."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a2/Geiko_Kimiha.jpg/330px-Geiko_Kimiha.jpg"}, {"key": "duration", "value": "2h 30m"}]', '[]'),
  ('a709b32e-34db-425c-8b4a-c35ccbc20d9b', 'Itoya & Loft stationery run', 'shop', 'Itoya, Ginza', 35.6717, 139.765, null, 64, true, '[{"key": "duration", "value": "1h 30m"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5b/Ginza-WAKO_at_night.jpg/330px-Ginza-WAKO_at_night.jpg"}, {"key": "info", "value": "12 storeys of Japan''s best stationery (est. 1904). Loft/Tokyu Hands nearby for the playful end."}]', '["Hobonichi techo", "Brush pens", "Washi tape", "MD paper notebooks"]'),
  ('c7ace3a7-7ca8-454b-b8b6-18f9a9e9de5a', 'Osaka Castle', 'place', 'Osaka Castle Park', 34.6873, 135.5259, null, 65, false, '[{"key": "info", "value": "The reconstructed samurai keep + moat park — ¥1,200. Go up for views, picnic in the grounds."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ca/Osaka_Castle_03bs3200.jpg/330px-Osaka_Castle_03bs3200.jpg"}, {"key": "duration", "value": "2h"}]', '[]'),
  ('1b072402-27eb-442a-9f68-20ee3c6c1712', 'Abeno Harukas 300', 'place', 'Tennoji', 34.6462, 135.5133, null, 66, false, '[{"key": "info", "value": "Japan''s tallest skyscraper (300 m) — glass-walled 360° deck, ¥1,500, open till 21:00."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/%E3%81%82%E3%81%B9%E3%81%AE%E3%83%8F%E3%83%AB%E3%82%AB%E3%82%B9.jpg/330px-%E3%81%82%E3%81%B9%E3%81%AE%E3%83%8F%E3%83%AB%E3%82%AB%E3%82%B9.jpg"}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('2fb82c36-76b9-4a9a-8f36-56312983b6a0', 'Tombori river cruise', 'experience', 'Dotonbori', 34.6689, 135.5013, null, 67, false, '[{"key": "info", "value": "20-min neon canal boat under the billboards, ~¥1,000."}, {"key": "duration", "value": "45m"}]', '[]'),
  ('7fe44059-7a89-4e1e-adc6-0fe89ccc13c1', 'Hozenji Yokocho', 'place', 'Off Dotonbori', 34.6673, 135.503, null, 68, false, '[{"key": "info", "value": "The moss-covered, water-splashed Buddha down a lantern alley — 2 min from the chaos. Free."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Osaka_Dotonbori_Ebisu_Bridge.jpg/330px-Osaka_Dotonbori_Ebisu_Bridge.jpg"}, {"key": "duration", "value": "30m"}]', '[]'),
  ('d953bcbd-7a65-40b7-9c97-4047795ab700', 'Den Den Town', 'shop', 'Nipponbashi', 34.6633, 135.5063, null, 69, false, '[{"key": "info", "value": "Osaka''s Akihabara — less crowded than Tokyo''s."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/69/Nipponbashi_Osaka_Japan01-r.jpg/330px-Nipponbashi_Osaka_Japan01-r.jpg"}]', '["Anime figures", "Retro games"]'),
  ('26a2340f-dddf-4476-9423-3653b3e3d8e0', 'Ura-Namba izakaya crawl', 'experience', 'Ura-Namba', 34.664, 135.504, null, 70, false, '[{"key": "info", "value": "Red-lantern backstreets of tiny 6-seat yakitori/sushi bars — the authentic drinking crawl. Drinks ¥300–600."}, {"key": "duration", "value": "3h"}]', '[]'),
  ('7a4f1fbb-d76c-495f-b718-bf1b6f76492c', 'Kaiyukan Aquarium', 'place', 'Tempozan', 34.6545, 135.4289, null, 71, false, '[{"key": "info", "value": "One of the world''s biggest aquariums — whale sharks in the central tank. ¥2,400–2,700; the giant Ferris wheel next door is ¥900."}, {"key": "duration", "value": "2h 30m"}]', '[]'),
  ('657f8393-5724-44fb-8d21-42eeaf056a13', 'Spa World', 'experience', 'Shinsekai', 34.6517, 135.506, null, 72, false, '[{"key": "info", "value": "Giant themed onsen complex — \"Europe\" & \"Asia\" bath zones, pools, 24-h baths. ¥1,200–1,500."}, {"key": "duration", "value": "3h"}]', '[]'),
  ('f07e2c34-48a9-4258-b364-fa1a0743f063', 'NGK comedy (Yoshimoto)', 'experience', 'Namba Grand Kagetsu', 34.6672, 135.5027, null, 73, false, '[{"key": "info", "value": "Japan''s largest comedy theater — manzai, sketches, slapstick Shinkigeki, 365 days/yr. ¥2,000–5,000; some shows use simple English/visual humor."}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('dac4c258-8295-413d-83da-1066f46cfc15', 'Namba Yasaka lion shrine', 'place', 'Namba', 34.6634, 135.497, null, 74, false, '[{"key": "info", "value": "The giant open-mouthed lion-head stage — Osaka''s most photogenic quirk. Free."}, {"key": "duration", "value": "30m"}]', '[]'),
  ('5be28bd3-060e-43cb-a81c-c53e97ecc71e', 'Sumiyoshi Taisha', 'place', 'Sumiyoshi', 34.6124, 135.493, null, 75, false, '[{"key": "info", "value": "~1,800-year-old shrine with the dramatic arched Sorihashi bridge — far fewer tourists."}, {"key": "duration", "value": "1h"}]', '[]'),
  ('97867e8e-4ab9-4bbc-a524-bf456dde958e', 'Takoyaki cooking class', 'experience', 'Namba', 34.666, 135.501, null, 76, false, '[{"key": "info", "value": "Grill your own takoyaki + okonomiyaki with a local (~3 h incl. sake/beer), ~¥6,000–8,000 — great group activity."}, {"key": "duration", "value": "1h 30m"}]', '[]'),
  ('5f70ee04-c986-4780-b17f-6e0153b08cc3', 'Himeji Castle', 'place', 'Himeji (~30 min shinkansen)', 34.8394, 134.6939, null, 77, false, '[{"key": "info", "value": "The White Heron — one of the finest surviving original castles on Earth (UNESCO). ¥2,500 (under-18 free); +Koko-en garden combo ¥2,600. Pairs with Kobe."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Himeji_castle_in_may_2015.jpg/330px-Himeji_castle_in_may_2015.jpg"}, {"key": "duration", "value": "3h"}]', '[]'),
  ('42adc762-bdbd-4c85-8914-77ac5739c1dc', 'Koyasan temple stay', 'experience', 'Mount Koya (~1.5–2 h from Namba)', 34.213, 135.585, null, 78, false, '[{"key": "info", "value": "Sleep in a working temple (shukubo, ~¥12,000–40,000 pp with monks'' vegetarian meals), walk the lantern-lit Okunoin cemetery at night, join 6am fire ritual.\n⚠ The one must-book-ahead item in Kansai — 1–2+ months for October."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/17/Danjogaran_Koyasan12n3200.jpg/330px-Danjogaran_Koyasan12n3200.jpg"}, {"key": "duration", "value": "5h"}]', '[]'),
  ('b1fbba08-e3ea-4a38-affb-4dbbd78ce6f9', 'Minoo Falls & momiji tempura', 'place', 'Minoo (~30 min from Umeda)', 34.8533, 135.4715, null, 79, false, '[{"key": "info", "value": "Easy 2.7 km forest trail to a 33 m waterfall — snack on batter-fried maple leaves (a 1,300-year-old tradition). Free; foliage peaks mid-Nov."}, {"key": "duration", "value": "3h"}]', '[]'),
  ('f9fe6b2a-821a-4b89-b642-4547094a0ddf', 'Mt Rokko night view', 'place', 'Kikuseidai, Kobe', 34.778, 135.233, null, 80, false, '[{"key": "info", "value": "One of Japan''s \"three great night views\" over Kobe + Osaka bay — ropeway from Sannomiya; pairs with the Arima finish."}, {"key": "duration", "value": "3h"}]', '[]'),
  ('a66fc1d2-8ff9-44e5-b04d-30d4770d3bbc', 'Lake Biwa / Hikone Castle', 'place', 'Shiga (~50 min)', 35.2766, 136.2518, null, 81, false, '[{"key": "info", "value": "A National Treasure original castle (¥1,000 incl. Genkyu-en garden), lakeside cycling, and I.M. Pei''s mountaintop Miho Museum (check seasonal open dates)."}, {"key": "duration", "value": "7h"}]', '[]'),
  ('a2d3b5c9-7e1f-46b9-91a8-b2c304d75228', 'Kinosaki Onsen (overnight)', 'experience', 'Kinosaki (~2.5 h)', 35.625, 134.8144, null, 82, false, '[{"key": "info", "value": "The definitive onsen-town stroll — seven public baths, canal in yukata + geta. Yumepa day pass ¥1,500; Oct–Dec is peak, book lodging early."}, {"key": "duration", "value": "8h"}]', '[]'),
  ('5b2573a5-b599-4f6a-83ff-45c9f0e5dc33', 'Amanohashidate sandbar', 'place', 'Miyazu Bay (~2 h+)', 35.567, 135.1902, null, 83, false, '[{"key": "info", "value": "One of Japan''s Three Great Views — view it upside-down through your legs (matanozoki) so it becomes a bridge to heaven. Chairlift ¥850."}, {"key": "duration", "value": "7h"}]', '[]'),
  ('c1389fc1-79b3-4e2b-af66-0786c6c2f9cf', 'Nachi Falls pilgrimage', 'place', 'Kumano (~4 h — overnight)', 33.669, 135.8898, null, 84, false, '[{"key": "info", "value": "Japan''s tallest single-drop waterfall (133 m) + the vermilion pagoda — the postcard of spiritual Japan, on the Kumano Kodo. Honestly an overnight."}, {"key": "duration", "value": "8h"}]', '[]'),
  ('33fa88a1-0740-4dea-b94e-8d988d65b334', 'Wakayama & Tomogashima', 'experience', 'Wakayama (~1 h from Namba)', 34.226, 135.171, null, 85, false, '[{"key": "info", "value": "Castle views, the theatrical tuna-cutting show at Kuroshio Market, and the Laputa-like ruined island forts of Tomogashima (20-min ferry — check weather)."}, {"key": "duration", "value": "8h"}]', '[]'),
  ('c0a3198b-52ee-43cf-8a0d-67a3a4a23a4c', '✈ Bengaluru → Tokyo · Cathay Pacific', 'transit', 'Haneda / Narita', 35.5494, 139.7798, 'd1', 0, true, '[{"key": "transit:mode", "value": "Flight"}, {"key": "transit:depart", "value": "12:35"}, {"key": "transit:duration", "value": "3h 30m"}, {"key": "info", "value": "Cathay Pacific: dep Bengaluru 01:15 IST Oct 14 → lands Tokyo 16:05 JST the same day. Immigration + luggage ≈ 1h."}]', '[]'),
  ('2e0128a4-629f-4ae4-8234-5286419ba88b', 'Haneda → Shinjuku', 'transit', 'Haneda Airport', 35.5494, 139.7798, 'd1', 1, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "transit:depart", "value": "17:30"}, {"key": "transit:duration", "value": "40m"}]', '[]'),
  ('4d95ae5c-5cf9-45c0-be34-b271244e03ed', 'Omoide Yokocho yakitori', 'food', 'Omoide Yokocho, Shinjuku', 35.6939, 139.6994, 'd1', 2, true, '[{"key": "time", "value": "19:30"}]', '["Yakitori", "Motsu nikomi"]'),
  ('1e26cc7c-93a0-4f79-955a-0614f3f4cb4d', 'Tokyo Met Gov night view', 'place', 'Tokyo Metropolitan Government Bldg', 35.6896, 139.6917, 'd1', 3, true, '[{"key": "info", "value": "FREE 45F observatory (202 m) — the best free panorama; Skytree and Fuji on clear days.\nNightly projection-mapping show on the building, sunset–~21:45. Open ~09:30–22:00."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b2/Skyscrapers_of_Shinjuku_2009_January.jpg/330px-Skyscrapers_of_Shinjuku_2009_January.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "21:00"}]', '[]'),
  ('9e7323be-b221-4204-ab84-028edffc0d55', 'Fushimi Inari full loop', 'place', 'Fushimi Inari Taisha', 34.9671, 135.7727, 'd10', 0, true, '[{"key": "info", "value": "The 10,000 torii. The full Mt Inari loop is 2–3 h and blissfully empty before 07:30.\nMost people quit at the Yotsutsuji viewpoint — keep going for solitude."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0e/Torii_path_with_lantern_at_Fushimi_Inari_Taisha_Shrine%2C_Kyoto%2C_Japan.jpg/330px-Torii_path_with_lantern_at_Fushimi_Inari_Taisha_Shrine%2C_Kyoto%2C_Japan.jpg"}, {"key": "duration", "value": "2h 30m"}, {"key": "time", "value": "07:30"}]', '[]'),
  ('fb3d1bad-99bb-4efa-ae9b-9890fb875ebb', 'Kimono day — wear your Tōji find', 'experience', 'Gion / Gojo', 35.0037, 135.7788, 'd10', 1, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Young_Woman_at_Kennin-ji_Zen_Temple_-_Kyoto_-_Japan_-_01_%2847929418887%29.jpg/330px-Young_Woman_at_Kennin-ji_Zen_Temple_-_Kyoto_-_Japan_-_01_%2847929418887%29.jpg"}, {"key": "time", "value": "11:30"}, {"key": "duration", "value": "5h"}, {"key": "info", "value": "Suit up in the vintage kimono from the Tōji market (self-dressed, casual is fine) and walk Gion + Higashiyama in it. Fallback: rental shops around Gion (¥4-6k) if anyone wants the pro-dressed look with hair."}]', '[]'),
  ('71df4005-cfcc-4c04-aa0c-b439673eb8c8', 'Nishiki Market grazing', 'food', 'Nishiki Market', 35.005, 135.7649, 'd10', 2, true, '[{"key": "info", "value": "\"Kyoto''s kitchen\" — 400 m of stalls. Eat at the stall, not walking (frowned upon)."}, {"key": "time", "value": "15:30"}, {"key": "duration", "value": "1h 30m"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/ce/Nishiki_Ichiba_by_matsuyuki.jpg/330px-Nishiki_Ichiba_by_matsuyuki.jpg"}]', '["Tako tamago", "Soy-milk donut", "Yuba"]'),
  ('960575cc-08de-490b-9b57-47e07b67d2e8', 'Gion Corner show', 'experience', 'Gion Corner', 35.0027, 135.7754, 'd10', 3, true, '[{"key": "info", "value": "Sampler of 7 arts in one hour — tea, koto, ikebana, kyogen, bunraku and maiko Kyomai dance. ¥3,150.\nShows 18:00 & 19:00 — verify the current schedule and book ahead."}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "18:00"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/150124_Gion_Kyoto_Japan01s3.jpg/330px-150124_Gion_Kyoto_Japan01s3.jpg"}]', '[]'),
  ('0a535d63-5ed0-480d-aec1-4742760c673c', 'Last Kyoto night — Pontocho', 'food', 'Pontocho / Kiyamachi', 35.009, 135.7706, 'd10', 4, true, '[{"key": "time", "value": "19:30"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Pontocho_by_Wolfiewolf_in_Nabeyacho%2C_Kyoto.jpg/330px-Pontocho_by_Wolfiewolf_in_Nabeyacho%2C_Kyoto.jpg"}]', '[]'),
  ('c051d0d2-9623-4abd-844a-b9926f0e7357', 'Kyoto → Osaka', 'transit', 'Kyoto Station', 34.9858, 135.7588, 'd11', 0, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "transit:depart", "value": "09:00"}, {"key": "transit:duration", "value": "30m"}]', '[]'),
  ('dbc6e0ef-90c3-4cc9-9809-986ba13d887c', 'Kuromon Ichiba grazing', 'food', 'Kuromon Ichiba Market', 34.6656, 135.5065, 'd11', 1, true, '[{"key": "info", "value": "600 m, 100+ stalls — \"Osaka''s Kitchen\". Morning–afternoon graze; also knives and kitchenware to take home."}, {"key": "time", "value": "10:30"}, {"key": "duration", "value": "1h 30m"}]', '["Otoro", "Grilled scallop", "Wagyu skewer"]'),
  ('386d2eef-466a-4552-89b8-d1359017228a', 'America-mura streetwear', 'shop', 'Amerikamura, Triangle Park', 34.672, 135.4977, 'd11', 2, true, '[{"key": "time", "value": "12:30"}, {"key": "duration", "value": "1h 30m"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/ee/Amerikamura.jpg/330px-Amerikamura.jpg"}]', '["Vintage thrift", "Sneakers", "Records"]'),
  ('3d038abc-a7c3-41f6-806b-f7cf1ee72dc2', 'Shinsekai & Tsutenkaku', 'place', 'Shinsekai', 34.6525, 135.5063, 'd11', 3, true, '[{"key": "info", "value": "Retro-Showa neon district — kushikatsu birthplace (Daruma, since 1929), cheapest beers in town; tower from ¥1,500."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/9/95/Shinsekai_and_Tsutenkaku_at_night_2019-04-12.jpg/330px-Shinsekai_and_Tsutenkaku_at_night_2019-04-12.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "14:00"}]', '[]'),
  ('3e644eb5-7050-47fa-b41a-1c8d1c3e4995', 'Dotonbori & Glico sign', 'experience', 'Ebisubashi Bridge, Dotonbori', 34.6687, 135.5013, 'd11', 4, true, '[{"key": "info", "value": "Kuidaore — eat till you drop. Takoyaki ~¥500–700 a tray, okonomiyaki ~¥900–1,400, kushikatsu ~¥120–200 a skewer (NO double-dipping — iron rule).\nThe arms-up Glico pose on Ebisubashi is best at blue hour."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/f/f4/Osaka_Dotonbori_Ebisu_Bridge.jpg/330px-Osaka_Dotonbori_Ebisu_Bridge.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "16:00"}]', '["Takoyaki", "Okonomiyaki", "Kushikatsu"]'),
  ('1e197f00-5837-4c66-bc3f-781db18eea38', 'Osaka → Arima Onsen', 'transit', 'Umeda', 34.7025, 135.4959, 'd11', 5, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "transit:depart", "value": "17:45"}, {"key": "transit:duration", "value": "1h 15m"}]', '[]'),
  ('edae4cd1-0c8d-4b4e-9f9f-3c0f5fc5bea0', 'Arima Onsen ryokan', 'experience', 'Arima Onsen', 34.7975, 135.2478, 'd11', 6, true, '[{"key": "info", "value": "Japan''s oldest hot-spring town — gold (kinsen) and silver (ginsen) baths, right behind Kobe.\nBook the ryokan 12–16 weeks ahead for October."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/170811_Rokko-Arima_Ropeway_Kobe_Japan00n.jpg/330px-170811_Rokko-Arima_Ropeway_Kobe_Japan00n.jpg"}, {"key": "duration", "value": "4h"}, {"key": "time", "value": "19:00"}]', '[]'),
  ('d60a0037-af7f-4a12-9c85-d99978b609f4', 'Morning kinsen soak', 'experience', 'Arima Onsen', 34.7976, 135.248, 'd12', 0, true, '[{"key": "time", "value": "07:30"}, {"key": "duration", "value": "2h"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/2c/170811_Rokko-Arima_Ropeway_Kobe_Japan00n.jpg/330px-170811_Rokko-Arima_Ropeway_Kobe_Japan00n.jpg"}]', '[]'),
  ('b17322f9-e8b4-40be-8302-56969ae72b2a', 'Arima → KIX · limousine bus', 'transit', 'Sannomiya Station', 34.6946, 135.1956, 'd12', 1, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "info", "value": "Allow ~2 h + buffer to KIX (via Osaka / Nankai or the Bay Shuttle)."}, {"key": "transit:depart", "value": "11:00"}, {"key": "transit:duration", "value": "1h 20m"}]', '[]'),
  ('67c34518-f1c1-4191-9575-02095c48dcc8', 'Kobe beef lunch', 'food', 'Sannomiya, Kobe', 34.6946, 135.1956, 'd12', 2, false, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/RedDot_Burger.jpg/330px-RedDot_Burger.jpg"}, {"key": "info", "value": "Arima sits right behind Kobe — teppanyaki lunch + Nankinmachi Chinatown / harbour if time allows.\nSqueeze in at KIX if check-in is quick — otherwise it drops; the soak wins."}]', '["Kobe beef teppanyaki"]'),
  ('8582a57d-8d2c-4617-83cb-612c44d19c9e', '✈ KIX → Bengaluru · Singapore Airlines', 'transit', 'Kansai International Airport', 34.4347, 135.2441, 'd12', 3, true, '[{"key": "transit:mode", "value": "Flight"}, {"key": "transit:depart", "value": "16:50"}, {"key": "transit:duration", "value": "7h"}, {"key": "info", "value": "SQ via Singapore. Dep KIX 16:50 Oct 25 → arr BLR 10:35 Oct 26. At the airport by 14:30; Arima exit by 11:30 keeps ~3h slack."}]', '[]'),
  ('78744ca3-c1b6-4301-8dd1-7b7e4d774e51', 'Senso-ji & Kaminarimon', 'place', 'Senso-ji, Asakusa', 35.7148, 139.7967, 'd2', 0, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/43/Sensoji_2023.jpg/330px-Sensoji_2023.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "08:00"}, {"key": "info", "value": "Tokyo''s oldest temple (founded 645) + the great lantern gate. Free; grounds always open.\nGo by 08:00 — by 10:00 it''s a wall of people.\nApproach through the Nakamise-dori snack stalls — that IS the walk in."}]', '[]'),
  ('538cd69b-3762-421f-ac3f-6d899aa0aea2', 'Tokyo Skytree', 'place', 'Oshiage, Sumida', 35.7101, 139.8107, 'd2', 1, true, '[{"key": "info", "value": "634 m — Tembo Deck from ¥1,800 advance; +Galleria combo from ¥3,000."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/84/Tokyo_Skytree_2014_%E2%85%A2.jpg/330px-Tokyo_Skytree_2014_%E2%85%A2.jpg"}, {"key": "duration", "value": "2h"}, {"key": "time", "value": "09:45"}]', '[]'),
  ('df799dbc-d2eb-48c7-b85d-bb81edb4575b', 'Ameyoko Market', 'shop', 'Ameyoko, Ueno', 35.7095, 139.7745, 'd2', 2, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/5/5e/Ueno_20241210_133139.jpg/330px-Ueno_20241210_133139.jpg"}, {"key": "time", "value": "11:45"}, {"key": "duration", "value": "1h"}]', '["Dried seafood", "Sneakers", "Cosmetics"]'),
  ('5e0095d1-7c7d-44ae-8903-4ed0f43d235a', 'teamLab Planets', 'experience', 'Toyosu', 35.6496, 139.7898, 'd2', 3, true, '[{"key": "info", "value": "Wade barefoot through water rooms and a mirrored infinity garden — the most physical, viral teamLab. Wear shorts.\n¥3,200 (≈ ₹1,855), timed entry — book days ahead. Extended to end-2027."}, {"key": "Official site", "value": "https://www.teamlab.art/e/planets/"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e2/Teamlab_logo_RGB_color.png/330px-Teamlab_logo_RGB_color.png"}, {"key": "duration", "value": "2h 30m"}, {"key": "time", "value": "13:30"}]', '[]'),
  ('45245132-dafa-469b-a8ef-a0039d2c9568', 'Shibuya Sky sunset', 'place', 'Shibuya Scramble Square 47F', 35.658, 139.7026, 'd2', 4, true, '[{"key": "info", "value": "Open-air 360° roof at 229 m — the city''s best sunset deck.\nThe sunset slot sells out in ~2 minutes; tickets release ~2 weeks ahead at 00:00 JST. ¥2,500 advance / ¥3,000 door."}, {"key": "Official site", "value": "https://www.shibuya-sky.com/"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Shibuya_Scramble_Square_-_SHIBUYA_SKY_10.jpg/330px-Shibuya_Scramble_Square_-_SHIBUYA_SKY_10.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "17:00"}]', '[]'),
  ('8df29afe-0b44-43e7-8f9c-9c19ed3cb3f0', 'Shibuya Scramble + Hachiko', 'place', 'Shibuya Crossing', 35.6595, 139.7005, 'd2', 5, true, '[{"key": "info", "value": "Best free overhead angles: Mag''s Park rooftop or the Tsutaya Starbucks window."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3a/Shibuya_skyline_from_Tokyu_Plaza_in_Omotesando%2C_Harajuku%2C_Tokyo%2C_2024_May.jpg/330px-Shibuya_skyline_from_Tokyu_Plaza_in_Omotesando%2C_Harajuku%2C_Tokyo%2C_2024_May.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "18:45"}]', '[]'),
  ('becbe8b9-910c-4451-a911-a94a423146b8', 'Nonbei Yokocho hush bar', 'experience', 'Nonbei Yokocho, Shibuya', 35.6604, 139.7025, 'd2', 6, true, '[{"key": "hidden", "value": "night only"}, {"key": "info", "value": "\"Drunkard''s Alley\" — a sliver of tiny post-war bars steps from the Scramble; far more local than Golden Gai."}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "19:45"}]', '[]'),
  ('89ceed41-be57-4953-bc63-b37735dce6ab', 'Mt. Takao trek', 'group', null, null, null, 'd3', 0, true, '[{"key": "group:start", "value": "Tokyo"}, {"key": "group:end", "value": "Tokyo"}]', '[]'),
  ('d81e5192-9d51-4e92-b5b2-6810c3571a35', 'Tokyo → Mt. Takao', 'transit', 'Keio Shinjuku Station', 35.6906, 139.6994, 'd3', 0, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "transit:depart", "value": "07:30"}, {"key": "transit:duration", "value": "55m"}]', '[]'),
  ('197de962-5066-4e6b-801f-72ef89d2a162', 'Golden Gai night cap', 'experience', 'Golden Gai, Shinjuku', 35.6939, 139.7043, 'd3', 1, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/G2_Street_20090626_2.jpg/330px-G2_Street_20090626_2.jpg"}, {"key": "duration", "value": "2h"}, {"key": "time", "value": "21:00"}]', '[]'),
  ('41843a3a-5ca2-44b6-8cca-2a24737bd021', 'Trail 1 to the summit', 'experience', 'Trail 1, Mt. Takao', 35.633, 139.259, 'd3', 1, true, '[{"key": "info", "value": "Paved main route past shops and viewpoints; other numbered trails (e.g. Trail 6 along a stream) are wilder."}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Mount_Takao_20051023.jpg/330px-Mount_Takao_20051023.jpg"}, {"key": "duration", "value": "2h"}, {"key": "time", "value": "08:45"}]', '[]'),
  ('9c3a8bce-85bb-4ac4-b2eb-ee610272a572', 'Yakuo-in Temple', 'place', 'Yakuo-in, Mt. Takao', 35.6301, 139.2481, 'd3', 2, true, '[{"key": "info", "value": "Mountainside temple with tengu (goblin) imagery en route to the top."}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Mount_Takao_20051023.jpg/330px-Mount_Takao_20051023.jpg"}, {"key": "duration", "value": "45m"}, {"key": "time", "value": "10:00"}]', '[]'),
  ('ca442d79-a465-42d2-b865-aae8f3aa67e0', 'Summit + Fuji view', 'place', 'Mt. Takao summit (599 m)', 35.6254, 139.2437, 'd3', 3, true, '[{"key": "info", "value": "Clear-day Mt. Fuji panorama from the top."}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/73/Mount_Takao_20051023.jpg/330px-Mount_Takao_20051023.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "10:45"}]', '[]'),
  ('5c821a4b-cb85-4fe4-8433-e2ff600752f9', 'Cablecar / chairlift', 'experience', 'Takao-tozan Cable Car, Kiyotaki Station', 35.639, 139.2696, 'd3', 4, true, '[{"key": "info", "value": "The funicular climbs a 31° max grade — Japan''s steepest — in about 6 minutes; you can skip the first stretch or hike it instead.\n~¥490 one-way / ~¥950 round-trip (≈ ₹284 / ₹551)."}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/a/a0/1_zermatt_evening_2022.jpg/330px-1_zermatt_evening_2022.jpg"}, {"key": "duration", "value": "30m"}, {"key": "time", "value": "12:00"}]', '[]'),
  ('5f53d72c-a8ed-43a7-986c-c8d7c4432d33', 'Takaosan Onsen Gokurakuyu', 'experience', 'Keio Takaosan Onsen, Takaosanguchi', 35.642, 139.2705, 'd3', 5, true, '[{"key": "info", "value": "A large hot-spring complex right next to the station — the post-hike soak."}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c5/Takaosanguchi-Station-exit-march20-2016.jpg/330px-Takaosanguchi-Station-exit-march20-2016.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "12:40"}]', '[]'),
  ('8b0599fd-2b65-491d-9fd7-b2a5d5096d1e', 'Mt. Takao → Tokyo', 'transit', 'Takaosanguchi Station', 35.6323, 139.2699, 'd3', 6, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "group", "value": "89ceed41-be57-4953-bc63-b37735dce6ab"}, {"key": "transit:depart", "value": "14:30"}, {"key": "transit:duration", "value": "55m"}]', '[]'),
  ('e633d240-3234-4e28-a9aa-76198047464c', 'Meiji Jingu', 'place', 'Meiji Shrine, Harajuku', 35.6764, 139.6993, 'd4', 0, true, '[{"key": "info", "value": "Serene shrine in a 100,000-tree forest — instant calm two minutes from Harajuku. You may catch a wedding procession."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8b/Meiji_Jingu_2023-3.jpg/330px-Meiji_Jingu_2023-3.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "09:00"}]', '[]'),
  ('e2880eed-091a-4371-bbaf-4dc87000a545', 'Takeshita Street', 'shop', 'Takeshita-dori, Harajuku', 35.6716, 139.7031, 'd4', 1, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/bd/JRE-Harajuku-Station-07.jpg/330px-JRE-Harajuku-Station-07.jpg"}, {"key": "time", "value": "11:00"}, {"key": "duration", "value": "1h 30m"}]', '["Crepes", "Vintage tees", "Kawaii socks"]'),
  ('048ca1c8-03ae-4205-92cb-b01164117bb4', 'Akihabara arcades & gachapon', 'experience', 'Akihabara Electric Town', 35.6984, 139.7731, 'd4', 2, true, '[{"key": "info", "value": "GiGO / Taito mega-arcades (~¥100 a play), Super Potato retro games, Gachapon Kaikan capsule halls (¥300–500 a spin), Yodobashi + Mandarake shopping."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Sotokanda%2C_Akihabara_Electric_Town_at_night_20231114.png/330px-Sotokanda%2C_Akihabara_Electric_Town_at_night_20231114.png"}, {"key": "duration", "value": "2h"}, {"key": "time", "value": "14:00"}]', '[]'),
  ('22404eae-697a-4988-aaff-dae81ce57e05', 'Maid cafe (@home cafe)', 'experience', '@home cafe, Akihabara', 35.7008, 139.7717, 'd4', 3, true, '[{"key": "info", "value": "The classic Akiba rabbit hole — entry + set ~¥1,500–3,000 (≈ ₹870–1,740)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/78/Maid_cafe_4.jpg/330px-Maid_cafe_4.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "16:00"}]', '[]'),
  ('d24a04d2-878a-4feb-8118-b8db39fe41a5', 'Nakano Broadway', 'shop', 'Nakano Broadway', 35.7086, 139.6657, 'd4', 4, true, '[{"key": "info", "value": "Mandarake HQ — the retro/collector''s maze. Vintage anime cels, figures, watches — often cheaper and rarer than Akihabara."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7e/Tah%C5%8Dzan_J%C5%8Dganji_Temple%2C_Nakano_City%2C_Tokyo.jpg/330px-Tah%C5%8Dzan_J%C5%8Dganji_Temple%2C_Nakano_City%2C_Tokyo.jpg"}, {"key": "time", "value": "17:45"}, {"key": "duration", "value": "1h 30m"}]', '["Vintage anime cels", "Figures", "Retro games"]'),
  ('02728147-b0c3-46a9-8038-4a8d9469e0fe', 'Womb club night', 'experience', 'WOMB, Shibuya', 35.6553, 139.6946, 'd4', 5, true, '[{"key": "info", "value": "Legendary multi-floor club — techno/house, monster sound system. Cover ¥3,000–5,000 (usually incl. a drink), doors ~23:00–05:00.\nAlternatives: ZeroTokyo / ageHa event nights, or an all-night karaoke room."}, {"key": "duration", "value": "3h"}, {"key": "time", "value": "23:00"}]', '[]'),
  ('a2c750bf-cc0f-43d8-9402-d05a0b51fcb0', 'Oedo Antique Market', 'shop', 'Tokyo International Forum', 35.6767, 139.7638, 'd5', 0, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Tokyo_International_Forum_-_Marunouchi.jpg/330px-Tokyo_International_Forum_-_Marunouchi.jpg"}, {"key": "time", "value": "09:30"}, {"key": "duration", "value": "2h"}, {"key": "info", "value": "Runs 1st & 3rd Sundays — Oct 19 is the 3rd Sunday (verify 2026 dates). Antiques, kimono, ceramics, ukiyo-e.\nBackup: Nogi-jinja / Shinjuku flea markets.\nRuns 9:00-16:00, usually 1st & 3rd Sundays — Oct 18 is the 3rd Sunday, but VERIFY at antique-market.jp (dates occasionally shift)."}]', '["Vintage kimono", "Ceramics", "Ukiyo-e prints", "Kokeshi doll", "Ukiyo-e print", "Old tea bowls"]'),
  ('f79f1c90-49dd-4f67-8c9d-d8cdd2adf486', 'Kappabashi Kitchen Town', 'shop', 'Kappabashi, Asakusa', 35.7139, 139.7886, 'd5', 1, true, '[{"key": "info", "value": "~1 km of chef supplies — knives, ceramics, and the famous plastic food samples."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Kappabashi-dori_streetcorner_%28Kitchen_town_-_southern_end%29_Tokyo_Japan.jpg/330px-Kappabashi-dori_streetcorner_%28Kitchen_town_-_southern_end%29_Tokyo_Japan.jpg"}, {"key": "time", "value": "12:30"}, {"key": "duration", "value": "1h 30m"}]', '["Japanese knife", "Plastic food sample", "Santoku knife", "Engraved chopsticks", "Plastic-food magnet"]'),
  ('c5049a5d-2f19-4793-95d6-fb0d50ebe251', 'Yoyogi Park buskers', 'experience', 'Yoyogi Park', 35.6712, 139.6949, 'd5', 2, false, '[{"key": "info", "value": "Sunday = buskers and the famous rockabilly dancers. Free."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/7/7a/Twice_260618.jpg/330px-Twice_260618.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "15:00"}]', '[]'),
  ('bf038aed-8f6e-47e3-a4b4-308c9e5e8365', 'Golden Gai by day', 'place', 'Golden Gai, Shinjuku', 35.6939, 139.7043, 'd5', 3, true, '[{"key": "info", "value": "~200 shoebox theme bars in a lantern maze — eerily photogenic and calm in daylight.\nReturn after dark: expect a ¥500–1,500 seat charge per bar."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/8d/G2_Street_20090626_2.jpg/330px-G2_Street_20090626_2.jpg"}, {"key": "duration", "value": "30m"}, {"key": "time", "value": "16:30"}]', '[]'),
  ('00602983-5cc4-4ba0-abbf-26794a6301cf', 'Don Quijote late-night haul', 'shop', 'Don Quijote (24 h, citywide)', 35.6605, 139.6982, 'd5', 4, true, '[{"key": "time", "value": "20:00"}, {"key": "duration", "value": "1h 30m"}]', '["KitKat variety", "Face masks", "Strange snacks", "Japan-only KitKat box", "Megrhythm steam eye masks", "LuLuLun sheet masks", "Pain-relief patches", "Melty Kiss"]'),
  ('dd6fedbd-df1c-48a8-a1d8-fd03fc714e6e', 'Shinjuku → Hakone-Yumoto', 'transit', 'Odakyu Shinjuku (Romancecar)', 35.6896, 139.6983, 'd6', 0, true, '[{"key": "transit:mode", "value": "Train"}, {"key": "transit:duration", "value": "1h 25m"}, {"key": "info", "value": "Buy the Hakone Freepass at Shinjuku (~¥7,100 / 2-day) — covers the whole loop: mountain train, cablecar, ropeway, buses and the Lake Ashi boat."}, {"key": "transit:depart", "value": "08:00"}]', '[]'),
  ('ddf535f9-1401-44ca-95ce-e044c06c363e', 'Hakone Open-Air Museum', 'place', 'Hakone Open-Air Museum', 35.245, 139.053, 'd6', 1, true, '[{"key": "info", "value": "Sculpture park with a Picasso pavilion and the stained-glass tower. ¥2,000 door / ¥1,800 online. 9:00–17:00."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/View_of_Mount_Fuji_from_Lake_Ashi.jpg/330px-View_of_Mount_Fuji_from_Lake_Ashi.jpg"}, {"key": "duration", "value": "2h 30m"}, {"key": "time", "value": "10:00"}]', '[]'),
  ('d2722733-7297-40b2-b868-fd8f78547eaf', 'Owakudani black eggs', 'experience', 'Owakudani Valley', 35.2445, 139.0195, 'd6', 2, true, '[{"key": "info", "value": "Live volcanic valley reached by ropeway. A kuro-tamago boiled in the springs is said to add 7 years to your life. Best Fuji views on clear days."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Owakudani_-_Hakone_%2827369344357%29.jpg/330px-Owakudani_-_Hakone_%2827369344357%29.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "13:30"}]', '["Kuro-tamago (black egg)"]'),
  ('c518b881-f920-4817-83ee-b57df21196be', 'Lake Ashi pirate cruise', 'place', 'Lake Ashi', 35.202, 139.0246, 'd6', 3, true, '[{"key": "info", "value": "Mock galleon across the lake (~25–40 min) — covered by the Freepass. Torii + Fuji views."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/260505_Moto-Hakone_Hakone_Japan01s3.jpg/330px-260505_Moto-Hakone_Hakone_Japan01s3.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "15:00"}]', '[]'),
  ('632eadc4-8826-4c7b-bb42-d399349fbc14', 'Hakone Shrine torii', 'place', 'Hakone Shrine, Moto-Hakone', 35.2048, 139.0256, 'd6', 4, true, '[{"key": "info", "value": "The vermilion \"Torii of Peace\" standing in the lake — iconic photo, expect a queue."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/View_of_Mount_Fuji_from_Lake_Ashi.jpg/330px-View_of_Mount_Fuji_from_Lake_Ashi.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "16:15"}]', '[]'),
  ('d3141512-99e2-41fc-adf8-08889325cd6c', 'Onsen ryokan night', 'experience', 'Hakone-Yumoto', 35.2324, 139.1069, 'd6', 5, true, '[{"key": "info", "value": "Kaiseki dinner + baths. Autumn = crisp air and better Fuji visibility.\nBook the ryokan 12–16 weeks ahead for October."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/41/Onsen_in_Nachikatsuura%2C_Japan.jpg/330px-Onsen_in_Nachikatsuura%2C_Japan.jpg"}, {"key": "duration", "value": "4h"}, {"key": "time", "value": "17:00"}]', '[]'),
  ('5e517c04-b08f-4761-acb2-dfdc23e3bb49', 'Old Tokaido cedar avenue', 'place', 'Moto-Hakone', 35.194, 139.026, 'd7', 0, true, '[{"key": "info", "value": "Walk the Edo-era stone highway under ~400-year-old cedars — short and atmospheric."}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "09:00"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/b/b5/View_of_Mount_Fuji_from_Lake_Ashi.jpg/330px-View_of_Mount_Fuji_from_Lake_Ashi.jpg"}]', '[]'),
  ('b8aae354-e2af-4d40-814e-5e761eb4fabe', 'Odawara → Kyoto', 'transit', 'Odawara Station', 35.2565, 139.1552, 'd7', 1, true, '[{"key": "transit:mode", "value": "Shinkansen"}, {"key": "transit:duration", "value": "2h 05m"}, {"key": "info", "value": "Reserve seats via smartEX/Klook. Use Suica/ICOCA — the JR Pass does NOT pay off on this route."}, {"key": "transit:depart", "value": "12:15"}]', '[]'),
  ('2069d396-570d-43ff-b2dc-0896c0b5ee60', 'Kiyomizu-dera', 'place', 'Higashiyama', 34.9949, 135.785, 'd7', 2, true, '[{"key": "info", "value": "The giant wooden stage over the hillside. ¥400 — opens ~6am, a rare early-open icon: go 6–7am for empty terraces. Autumn light-up from Nov 22."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/3c/Kiyomizu.jpg/330px-Kiyomizu.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "16:00"}]', '[]'),
  ('38321875-63e9-4302-87f0-8ea223f12109', 'Ninenzaka & Sannenzaka', 'place', 'Higashiyama', 34.9966, 135.781, 'd7', 3, true, '[{"key": "info", "value": "The preserved stone-paved slopes everyone pictures as old Kyoto."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/66/Pedestrian_road_with_pavements_and_paper_umbrellas%2C_Higashiyama-ku%2C_Kyoto%2C_Japan%2C_early_morning.jpg/330px-Pedestrian_road_with_pavements_and_paper_umbrellas%2C_Higashiyama-ku%2C_Kyoto%2C_Japan%2C_early_morning.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "17:30"}]', '[]'),
  ('3e80769b-299b-4feb-9022-9cf1b3ac2aea', 'Ishibekoji lane wander', 'place', 'Ishibe-koji, Higashiyama', 34.9986, 135.7805, 'd7', 4, true, '[{"key": "hidden", "value": "secret"}, {"key": "info", "value": "Kyoto''s most beautiful lane — stone-paved, lantern-lit, no crowds. Keep it quiet."}, {"key": "duration", "value": "30m"}, {"key": "time", "value": "18:15"}]', '[]'),
  ('4f5ac9e6-6987-4077-b8f7-ee537670caef', 'Yasaka Shrine', 'place', 'Yasaka Shrine, Gion', 35.0037, 135.7786, 'd7', 5, true, '[{"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/2/23/150124_Gion_Kyoto_Japan01s3.jpg/330px-150124_Gion_Kyoto_Japan01s3.jpg"}, {"key": "time", "value": "18:40"}, {"key": "duration", "value": "45m"}]', '[]'),
  ('e2a70f3d-c4ef-43c6-a327-ac7718fea53e', 'Pontocho lantern dinner', 'food', 'Pontocho Alley', 35.0095, 135.7708, 'd7', 6, true, '[{"key": "info", "value": "Kyoto''s most atmospheric lane — one person wide, lantern-lit, riverside. Reserve a river-view terrace; roll on to Kiyamachi after."}, {"key": "time", "value": "19:30"}, {"key": "duration", "value": "1h 30m"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/6/68/Pontocho_by_Wolfiewolf_in_Nabeyacho%2C_Kyoto.jpg/330px-Pontocho_by_Wolfiewolf_in_Nabeyacho%2C_Kyoto.jpg"}]', '[]'),
  ('e9940a9a-4531-4f2c-a19d-92ad36eb5bd6', 'Arashiyama Bamboo Grove', 'place', 'Arashiyama', 35.017, 135.6716, 'd8', 0, true, '[{"key": "info", "value": "The emerald corridor. Before 8am is the only way to get it near-empty — enter via Tenryu-ji''s back gate."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Arashiyama%2C_Part_II_-_Arashiyama7534.jpg/330px-Arashiyama%2C_Part_II_-_Arashiyama7534.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "08:00"}]', '[]'),
  ('088a2810-41c3-4116-8c46-0ad5df8c2d58', 'Tenryu-ji', 'place', 'Tenryu-ji, Arashiyama', 35.0158, 135.6739, 'd8', 1, true, '[{"key": "info", "value": "UNESCO Zen temple; the Sogenchi pond garden borrows the mountains. ¥500 (garden)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c2/Arashiyama%2C_Part_II_-_Arashiyama7534.jpg/330px-Arashiyama%2C_Part_II_-_Arashiyama7534.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "08:50"}]', '[]'),
  ('ec87b422-c1c6-48ac-93f9-aaac9d928d03', 'Sagano countryside cycling', 'experience', 'Sagano, Arashiyama', 35.019, 135.667, 'd8', 2, true, '[{"key": "info", "value": "Rent bikes near the station and ride the rural lanes — rice fields, Adashino, Okochi Sanso, Saga-Toriimoto old street. Relaxed, green, un-touristy."}, {"key": "duration", "value": "3h"}, {"key": "time", "value": "10:30"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/4/47/Sagano_scenic_railway_hotsukyo.jpg/330px-Sagano_scenic_railway_hotsukyo.jpg"}]', '[]'),
  ('ade1e15b-82db-4384-abe2-406bfecc7f9c', 'Iwatayama Monkey Park', 'experience', 'Iwatayama, Arashiyama', 35.0093, 135.6779, 'd8', 3, false, '[{"key": "info", "value": "20-min climb to wild snow monkeys + the best panorama of Kyoto. ¥800, cash only, 9:00–16:00."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Iwatayama_Monkey_Park.jpg/330px-Iwatayama_Monkey_Park.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "14:00"}]', '[]'),
  ('5bde8c6b-c21a-40fe-ad6f-2c5c4bb27117', 'Tōji temple flea market', 'shop', 'Tō-ji, Minami-ku, Kyoto', 34.9807, 135.7477, 'd8', 4, true, '[{"key": "time", "value": "15:30"}, {"key": "duration", "value": "1h 30m"}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/1/1f/Toji_2015.JPG/330px-Toji_2015.JPG"}, {"key": "info", "value": "Kōbō-ichi — the 21st of every month (your Arashiyama day!), dawn-16:00. Hundreds of stalls; wearable vintage kimono ¥1,000-5,000, cash only. Buy instead of renting (¥4-6k/day) — you keep it."}]', '["Vintage kimono + obi", "Tea cups", "Omamori & antiques"]'),
  ('6e00ad48-90e3-4ba2-b742-51a87707b0d0', 'Kamogawa river banks', 'place', 'Central Kyoto', 35.008, 135.772, 'd8', 5, true, '[{"key": "info", "value": "The locals'' living room — picnic with a depachika haul, buskers, evenly-spaced couples. Late afternoon best."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/3/30/Kamogawa_sakura.jpg/330px-Kamogawa_sakura.jpg"}, {"key": "duration", "value": "1h"}, {"key": "time", "value": "18:00"}]', '[]'),
  ('19ec8ff3-4faa-4f02-b5f4-e687a047e388', 'Nijo Castle', 'place', 'Central Kyoto', 35.0142, 135.7481, 'd9', 0, true, '[{"key": "info", "value": "The shogun''s castle with \"nightingale floors\" that chirp to foil ninja. ¥600; go late afternoon as temple crowds thin (last entry 16:00)."}, {"key": "image", "value": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/dd/NinomaruPalace.jpg/330px-NinomaruPalace.jpg"}, {"key": "duration", "value": "1h 30m"}, {"key": "time", "value": "08:45"}]', '[]'),
